DECLARE
  v_costo_cambio NUMERIC(12, 2);
  v_usuario_puede_editar BOOLEAN;
BEGIN
  v_costo_cambio := NEW.precio_costo;

  v_usuario_puede_editar :=
    COALESCE(auth.role() = 'service_role', false)
    OR public.auth_es_superadmin()
    OR (
      public.auth_es_dueno_o_superadmin()
      AND NEW.kiosco_id = public.auth_user_kiosco_id()
    );

  IF TG_OP = 'INSERT' THEN

    IF v_costo_cambio <> 0
       AND NOT v_usuario_puede_editar THEN
      RAISE EXCEPTION
        'Solo el dueño puede definir el costo del producto'
        USING ERRCODE = '42501';
    END IF;

    IF v_usuario_puede_editar THEN
      INSERT INTO public.producto_costos (
        producto_id,
        kiosco_id,
        precio_costo
      )
      VALUES (
        NEW.id,
        NEW.kiosco_id,
        v_costo_cambio
      )
      ON CONFLICT (producto_id) DO UPDATE
      SET kiosco_id = EXCLUDED.kiosco_id,
          precio_costo = EXCLUDED.precio_costo,
          fecha_actualizacion = now();
    END IF;

  ELSIF v_usuario_puede_editar THEN

    INSERT INTO public.producto_costos (
      producto_id,
      kiosco_id,
      precio_costo
    )
    VALUES (
      NEW.id,
      NEW.kiosco_id,
      v_costo_cambio
    )
    ON CONFLICT (producto_id) DO UPDATE
    SET kiosco_id = EXCLUDED.kiosco_id,
        precio_costo = EXCLUDED.precio_costo,
        fecha_actualizacion = now();

  ELSIF v_costo_cambio IS DISTINCT FROM OLD.precio_costo THEN

    IF NOT v_usuario_puede_editar THEN
      RAISE EXCEPTION
        'Solo el dueño puede modificar el costo del producto'
        USING ERRCODE = '42501';
    END IF;

  END IF;

  NEW.precio_costo := 0;

  RETURN NEW;
END;

DECLARE
  v_dueno_del_comercio boolean;
BEGIN
  IF COALESCE(auth.role() = 'service_role', false)
     OR public.auth_es_superadmin()
     OR (
       auth.uid() IS NULL
       AND auth.role() IS NULL
       AND session_user IN ('postgres', 'supabase_admin')
     ) THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.es_superadmin IS TRUE THEN
      RAISE EXCEPTION
        'Solo un superadmin puede conceder privilegios de superadmin.'
        USING ERRCODE = '42501';
    END IF;

    -- La política RLS existente exige dueño del mismo comercio para INSERT.
    RETURN NEW;
  END IF;

  IF OLD.es_superadmin IS TRUE THEN
    RAISE EXCEPTION
      'Solo un superadmin puede modificar o eliminar otro superadmin.'
      USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  IF NEW.es_superadmin IS DISTINCT FROM OLD.es_superadmin THEN
    RAISE EXCEPTION
      'Solo un superadmin puede cambiar los privilegios de superadmin.'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.kiosco_id IS DISTINCT FROM OLD.kiosco_id THEN
    RAISE EXCEPTION
      'La identidad y el comercio del perfil requieren administración de superadmin.'
      USING ERRCODE = '42501';
  END IF;

  v_dueno_del_comercio :=
    public.auth_es_dueno_o_superadmin()
    AND OLD.kiosco_id = public.auth_user_kiosco_id();

  IF (
    NEW.rol IS DISTINCT FROM OLD.rol
    OR NEW.activo IS DISTINCT FROM OLD.activo
    OR NEW.auth_user_id IS DISTINCT FROM OLD.auth_user_id
  )
  AND NOT COALESCE(v_dueno_del_comercio, false) THEN
    RAISE EXCEPTION
      'Solo el dueño del comercio puede cambiar rol, acceso o estado de un empleado.'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
